import json, os
random_seed = 2009
questions = []
id_counter = 1

def q(area, disc, ctx, text, pergunta, opts, gab, dif, taxa):
    global id_counter
    prefix = {"linguagens":"L","humanas":"H","natureza":"N","matematica":"M"}[area]
    qid = f"{prefix}2009_{id_counter:02d}"
    id_counter += 1
    return {"id":qid,"ano":2009,"area":area,"disciplina":disc,"contexto":ctx,"texto":text,"pergunta":pergunta,"opcoes":opts,"gabarito":gab,"dificuldade":dif,"taxaAcerto":taxa}

