questions.append(q("linguagens","portugues","Leia o texto abaixo para responder à questão.","Em 2009, o Brasil sediou a Reunião de Chefes de Estado e de Governo da Unasul. O encontro, realizado em Brasília, abordou temas como a integração regional e o desenvolvimento sustentável. O presidente Lula defendeu a criação de um banco sul-americano de desenvolvimento.","Assinale a alternativa em que a palavra destacada atua como conjunção integrante.",["O encontro abordou temas como a integração regional","O presidente defendeu a criação de um banco que financiaria projetos","Alguns dos quais questionavam a viabilidade financeira","A proposta gerou debate entre os participantes","O encontro, realizado em Brasília, abordou temas"],"A",3,38))
questions.append(q("linguagens","portugues","Leia o trecho abaixo para responder à questão.","Eu nasci sexta-feira, 13 de março, uma grande mancha de vinho tinto. Minha mãe disse: Minha filha, tudo isso vai passar. O poema expressa a fragilidade da condição humana diante do destino.","O sujeito da oração 'uma grande mancha de vinho tinto' é do tipo:",["Sujeito simples, oculto, de referência indefinida","Sujeito composto, oculto, de referência definida","Sujeito inexistente (oração sem sujeito)","Sujeito simples, oculto, de referência definida","Sujeito indeterminado"],"C",2,54))
